insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_struggle_6','struggle','verb','to have difficulty doing or understanding something','[{"senseId":"struggle_6_1","meaning":"to have difficulty doing or understanding something","acceptedParaphrases":["have a hard time","try hard but find it difficult"],"masteryContexts":[{"contextId":"u6_31_struggle_6_meaning","text":"Students who struggle with reading often avoid long texts, which makes the problem worse.","meaning":"to have difficulty doing or understanding something","wrongMeanings":["to be unwilling to start something","to be too tired to continue","to dislike what other people do"]},{"contextId":"u6_31_struggle_6_paraphrase","text":"Many small shops struggle to survive when a large supermarket opens nearby.","meaning":"to find it very hard to succeed","wrongMeanings":["to refuse to stay open late","to decide to sell more goods","to plan to move somewhere else"]}],"situationDistractors":["The train arrived on time, and the passengers stepped onto the platform.","Bella baked a cake for her brother’s birthday and decorated it with strawberries.","The coach praised the team after an easy victory.","Dana tidied her room and put the clean clothes in the wardrobe.","The ferry crossed the bay in under twenty minutes.","A neighbour offered to look after the cat for the weekend."],"gapDistractors":[{"contextId":"u6_31_struggle_6_gap_1","answer":"struggle","wrong":["agree","argue","quarrel"]},{"contextId":"u6_31_struggle_6_gap_2","answer":"struggle","wrong":["travel","arrive","hurry"]},{"contextId":"u6_31_struggle_6_gap_3","answer":"struggle","wrong":["agree","argue","quarrel"]}],"spellingErrors":["strugle","struggel","strugel","struggal","strugal","struggol"],"masteryPassages":[{"passageId":"u6_31_struggle_6_passage_1","contextId":"u6_31_struggle_6_gap_1","text":"Learning to read in a second language is slow work. Some children ____ for years with spelling, even though they speak fluently and enjoy stories.","answer":"struggle"},{"passageId":"u6_31_struggle_6_passage_2","contextId":"u6_31_struggle_6_gap_2","text":"Opening a business is rarely easy. In the first year, many owners ____ to pay the rent, because customers take time to find them.","answer":"struggle"}],"contextDependentParaphrases":[],"wrongParaphrases":["take a long break","make a quick choice","give a clear answer"],"misleadingDistractors":["to fight physically with another person","to succeed easily without any help","to refuse to do what is asked"],"teacherNote":"Unit 6 item (struggle_6), separate from the Unit 1 struggle item; shares only the lexical spelling list. Sense: to have difficulty doing or understanding something, often followed by with or to. The physical fight sense is not taught here."}]'::jsonb,'[]'::jsonb,'["struggle with a task","struggle to understand","struggle to keep up"]'::jsonb,'live'),
('vocab_awareness','awareness','noun','knowledge or understanding that something exists or is important','[{"senseId":"awareness_1","meaning":"knowledge or understanding that something exists or is important","acceptedParaphrases":["knowledge and understanding","recognition that a problem exists"],"masteryContexts":[{"contextId":"u6_32_awareness_meaning","text":"The campaign aims to raise awareness of the dangers of using a phone while crossing the road.","meaning":"knowledge that something is important","wrongMeanings":["anger that something is allowed","permission to do something risky","payment for doing something useful"]},{"contextId":"u6_32_awareness_paraphrase","text":"Travelling abroad gave her a greater awareness of how people in other countries live.","meaning":"understanding that something exists","wrongMeanings":["approval of how people choose","payment for how people work","memory of how people lived"]}],"situationDistractors":["The market opens at dawn, and farmers arrive with baskets of vegetables.","Kofi tied his shoelaces, picked up his bag and ran to the bus stop.","A thunderstorm cancelled the outdoor concert on Saturday evening.","The baker sold out of bread before nine o’clock.","Tomás painted the fence white and washed the brushes afterwards.","A group of cyclists stopped at the cafe on the corner."],"gapDistractors":[{"contextId":"u6_32_awareness_gap_1","answer":"awareness","wrong":["permission","payment","tolerance"]},{"contextId":"u6_32_awareness_gap_2","answer":"awareness","wrong":["shortage","weight","price"]},{"contextId":"u6_32_awareness_gap_3","answer":"awareness","wrong":["invitation","translation","punishment"]}],"spellingErrors":["awarness","awereness","awearness","awarenes","aweraness","awarenness"],"wordFamilyForms":[{"form":"awareness","partOfSpeech":"noun","example":"Public awareness of the dangers of sunburn has grown in recent years.","pedagogicallyUseful":true},{"form":"aware","partOfSpeech":"adjective","example":"Most drivers are aware of the speed limit near the school.","pedagogicallyUseful":true,"altExample":"Few shoppers are aware that the label refers to the weight of the packaging."},{"form":"unaware","partOfSpeech":"adjective","example":"Tom was completely unaware that his phone was ringing, because he was wearing headphones.","pedagogicallyUseful":true,"altExample":"Many residents remained unaware of the plan until the road was closed."}],"masteryPassages":[{"passageId":"u6_32_awareness_passage_1","contextId":"u6_32_awareness_gap_1","text":"Few people knew that the disease existed until the charity began its campaign. Since then, public ____ has risen, and more patients visit a doctor early.","answer":"awareness"},{"passageId":"u6_32_awareness_passage_2","contextId":"u6_32_awareness_gap_2","text":"A driver may look at the road and still miss a cyclist. The problem is often a lack of ____ of other road users, not poor eyesight.","answer":"awareness"}],"contextDependentParaphrases":[],"wrongParaphrases":["attention and effort","pride and respect","speed and accuracy"],"misleadingDistractors":["the ability to give full attention to one task","a feeling of pride in your own work","a rule that explains how to behave"],"teacherNote":"Uncountable in this sense: knowledge or understanding that something exists or is important (awareness of the risks, raise awareness). It is not concentration, which is the ability to give full attention to one thing. It is often followed by of."}]'::jsonb,'["aware","unaware"]'::jsonb,'["raise awareness","awareness of","public awareness"]'::jsonb,'live'),
('vocab_capacity','capacity','noun','the ability or potential to do, understand or hold something','[{"senseId":"capacity_1","meaning":"the ability or potential to do, understand or hold something","acceptedParaphrases":["natural ability","potential to do or understand"],"masteryContexts":[{"contextId":"u6_33_capacity_meaning","text":"People with a strong capacity for hard work often succeed even when they start with fewer advantages.","meaning":"the ability or potential to do something","wrongMeanings":["the wish to avoid something difficult","the habit of finishing early","the reward for doing something well"]},{"contextId":"u6_33_capacity_paraphrase","text":"The human brain has an enormous capacity to store information, although it cannot give attention to everything at once.","meaning":"the ability to hold or take in something","wrongMeanings":["the speed of moving from place to place","the habit of forgetting unimportant things","the cost of keeping something safe"]}],"situationDistractors":["Rain fell steadily as the cyclists climbed the hill.","The waiter carried a tray of drinks to the table by the window.","Ali spent the afternoon repairing his bicycle in the garage.","Ines bought a ticket and found a seat by the window.","The old clock in the square struck twelve.","Hot soup was served to everyone after the long walk."],"gapDistractors":[{"contextId":"u6_33_capacity_gap_1","answer":"capacity","wrong":["permission","invitation","reluctance"]},{"contextId":"u6_33_capacity_gap_2","answer":"capacity","wrong":["uniform","reputation","schedule"]},{"contextId":"u6_33_capacity_gap_3","answer":"capacity","wrong":["demand","excuse","refusal"]}],"spellingErrors":["capasity","capacitty","capacety","cappacity","capaciti","capacty"],"masteryPassages":[{"passageId":"u6_33_capacity_passage_1","contextId":"u6_33_capacity_gap_1","text":"Nobody is born knowing how to read, but almost every child has the ____ to learn it. Good teaching turns that potential into skill.","answer":"capacity"},{"passageId":"u6_33_capacity_passage_2","contextId":"u6_33_capacity_gap_2","text":"A beginner may play badly today and still show great promise. A good coach looks for the ____ to improve, not only for the score on the day.","answer":"capacity"}],"contextDependentParaphrases":[],"wrongParaphrases":["recent success","strong desire","fixed rule"],"misleadingDistractors":["the quantity of work a student has finished","a measure of how well someone is performing now","the size of a room or container"],"teacherNote":"Taught in its ability or potential sense: the ability or potential to do, understand or hold something (a capacity to learn, capacity for hard work). It describes potential, not current performance. The physical size of a container (the capacity of a tank) is not the focus here."}]'::jsonb,'[]'::jsonb,'["capacity to learn","capacity for","a limited capacity"]'::jsonb,'live'),
('vocab_feedback','feedback','noun','comments or information about performance that help someone to improve','[{"senseId":"feedback_1","meaning":"comments or information about performance that help someone to improve","acceptedParaphrases":["helpful comments","information about performance"],"masteryContexts":[{"contextId":"u6_34_feedback_meaning","text":"The manager gave the new employee useful feedback on how to speak more clearly to customers.","meaning":"comments that help someone to improve","wrongMeanings":["marks that decide a final result","rules that explain what to do","prizes that reward good work"]},{"contextId":"u6_34_feedback_paraphrase","text":"Fitness apps provide instant feedback on your speed and distance, so you can adjust your training.","meaning":"information about performance","wrongMeanings":["payment for finishing a task","advice about what to wear","instructions for starting a machine"]}],"situationDistractors":["The family sat on the beach and ate sandwiches while the children built a castle.","A bus driver waited at the stop for two minutes and then pulled away.","Lena packed her suitcase the night before the flight.","The farmer opened the gate and let the sheep cross the road.","Two friends shared a taxi to the airport.","Snow covered the village and the roads were closed."],"gapDistractors":[{"contextId":"u6_34_feedback_gap_1","answer":"feedback","wrong":["luggage","scenery","weather"]},{"contextId":"u6_34_feedback_gap_2","answer":"feedback","wrong":["uniforms","invoices","parcels"]},{"contextId":"u6_34_feedback_gap_3","answer":"feedback","wrong":["directions","permission","change"]}],"spellingErrors":["feedbak","fedback","feadback","feedbac","feed-bak","feebback"],"masteryPassages":[{"passageId":"u6_34_feedback_passage_1","contextId":"u6_34_feedback_gap_1","text":"The student handed in an essay and heard nothing for three weeks. Without ____, she did not know which mistakes to correct before the next one.","answer":"feedback"},{"passageId":"u6_34_feedback_passage_2","contextId":"u6_34_feedback_gap_2","text":"The app tells runners their speed after every kilometre. This instant ____ lets them slow down or speed up during the race.","answer":"feedback"}],"contextDependentParaphrases":[],"wrongParaphrases":["final marks","school rules","written tests"],"misleadingDistractors":["harsh criticism that makes people feel bad","a reward given for finishing a task","the final mark on an examination"],"teacherNote":"Uncountable noun: comments or information about performance that help someone to improve (give feedback, feedback on your work). It is not the same as criticism: good feedback also says what was done well. The sound-system sense (the loud noise from a microphone) is not taught."}]'::jsonb,'[]'::jsonb,'["give feedback","feedback on","positive feedback"]'::jsonb,'live'),
('vocab_respond','respond','verb','to answer or react to something','[{"senseId":"respond_1","meaning":"to answer or react to something","acceptedParaphrases":["give an answer","answer or react"],"masteryContexts":[{"contextId":"u6_35_respond_meaning","text":"When the interviewer asked about her weaknesses, she paused briefly and then began to respond calmly.","meaning":"to give an answer","wrongMeanings":["to ask a new question","to read a text aloud","to repeat what was said"]},{"contextId":"u6_35_respond_paraphrase","text":"Patients respond differently to the same medicine, so doctors often adjust the dose.","meaning":"to react to something","wrongMeanings":["to refuse to take something","to suffer from something","to prepare for something"]}],"situationDistractors":["The postman left a parcel on the doorstep and cycled to the next house.","The pupils sat down and opened their books at page twelve.","A guide led the group through the narrow streets to the old market.","A man in a yellow coat sold umbrellas outside the station.","The children built a tent in the garden with old sheets.","Lucas painted the kitchen wall pale green on Sunday."],"gapDistractors":[{"contextId":"u6_35_respond_gap_1","answer":"respond","wrong":["belong","travel","happen"]},{"contextId":"u6_35_respond_gap_2","answer":"respond","wrong":["belong","listen","refer"]},{"contextId":"u6_35_respond_gap_3","answer":"respond","wrong":["belong","happen","arrive"]}],"spellingErrors":["responed","respnd","resbond","respund","resspond","respont"],"wordFamilyForms":[{"form":"respond","partOfSpeech":"verb","example":"Companies must respond quickly when customers report a fault.","pedagogicallyUseful":true},{"form":"response","partOfSpeech":"noun","example":"The company’s response to the complaint arrived within an hour.","pedagogicallyUseful":true,"altExample":"The survey received a strong response from parents of young children."},{"form":"responsive","partOfSpeech":"adjective","example":"Patients prefer a responsive doctor who listens and answers questions quickly.","pedagogicallyUseful":true,"altExample":"A responsive website adjusts itself to the size of the screen."}],"masteryPassages":[{"passageId":"u6_35_respond_passage_1","contextId":"u6_35_respond_gap_1","text":"The teacher asked the class why the river had flooded. Nobody spoke at first, then one boy began to ____ with a simple, careful explanation.","answer":"respond"},{"passageId":"u6_35_respond_passage_2","contextId":"u6_35_respond_gap_2","text":"Doctors know that two people with the same illness may not react in the same way. One patient may ____ well to a medicine, while another feels no change at all.","answer":"respond"}],"contextDependentParaphrases":[],"wrongParaphrases":["ask a question","follow an order","make a note"],"misleadingDistractors":["to obey an instruction without thinking","to ask a question to start a discussion","to ignore what someone has said"],"teacherNote":"Taught as a verb: to answer or react to something, often in words (respond to a question, respond to feedback). It is not the same as obey: you can respond to an instruction by questioning it. It is usually followed by to."}]'::jsonb,'["response","responsive"]'::jsonb,'["respond to","respond quickly","respond positively"]'::jsonb,'live'),
('vocab_hesitation','hesitation','noun','a pause or delay caused by uncertainty or lack of confidence','[{"senseId":"hesitation_1","meaning":"a pause or delay caused by uncertainty or lack of confidence","acceptedParaphrases":["pause caused by doubt","delay caused by uncertainty"],"masteryContexts":[{"contextId":"u6_36_hesitation_meaning","text":"Without any hesitation, the lifeguard jumped into the water and swam towards the child.","meaning":"a pause caused by uncertainty","wrongMeanings":["a rush caused by excitement","a refusal caused by anger","a plan made with care"]},{"contextId":"u6_36_hesitation_paraphrase","text":"There was a moment of hesitation before he signed the contract, because he was not sure the salary was fair.","meaning":"a delay caused by doubt","wrongMeanings":["a mistake caused by haste","a refusal caused by anger","an argument caused by a payment"]}],"situationDistractors":["The cleaner emptied the bins and locked the side door.","Marta picked up her keys, locked the door and walked briskly to work.","The judge announced the winners and the crowd cheered loudly.","The orchestra tuned their instruments before the concert began.","Rain stopped just before the parade reached the square.","Priya sorted the letters into three piles on the desk."],"gapDistractors":[{"contextId":"u6_36_hesitation_gap_1","answer":"hesitation","wrong":["permission","payment","insurance"]},{"contextId":"u6_36_hesitation_gap_2","answer":"hesitation","wrong":["holiday","journey","invitation"]},{"contextId":"u6_36_hesitation_gap_3","answer":"hesitation","wrong":["uniform","microphone","handwriting"]}],"spellingErrors":["hesitaton","hesitasion","hesistation","hessitation","hesitashun","hesatation"],"wordFamilyForms":[{"form":"hesitation","partOfSpeech":"noun","example":"She accepted the offer without hesitation because she had wanted the job for years.","pedagogicallyUseful":true},{"form":"hesitate","partOfSpeech":"verb","example":"Please do not hesitate to ask for help if you do not understand the instructions.","pedagogicallyUseful":true,"altExample":"Doctors tell patients not to hesitate to call if the pain gets worse."},{"form":"hesitant","partOfSpeech":"adjective","example":"He gave a hesitant answer, as if he were not sure the figure was correct.","pedagogicallyUseful":true,"altExample":"The new player was hesitant at first, but she soon gained confidence."}],"masteryPassages":[{"passageId":"u6_36_hesitation_passage_1","contextId":"u6_36_hesitation_gap_1","text":"The climber looked down at the narrow ledge. After a long ____, she took a deep breath and stepped forward.","answer":"hesitation"},{"passageId":"u6_36_hesitation_passage_2","contextId":"u6_36_hesitation_gap_2","text":"The interviewer noticed every pause in the candidate’s answers. Her ____ suggested that she was unsure of the facts, even though her voice stayed calm.","answer":"hesitation"}],"contextDependentParaphrases":[],"wrongParaphrases":["quick decision","angry refusal","sudden success"],"misleadingDistractors":["a firm refusal to do something","a sudden and confident decision","a feeling of anger about a result"],"teacherNote":"A pause or delay caused by uncertainty or lack of confidence (a moment of hesitation, without hesitation). It is not the same as refusal: a person who shows hesitation may still agree in the end."}]'::jsonb,'["hesitate","hesitant"]'::jsonb,'["without hesitation","a moment of hesitation","show hesitation"]'::jsonb,'live'),
('vocab_independent','independent','adjective','able to work, think or make decisions without relying heavily on others','[{"senseId":"independent_1","meaning":"able to work, think or make decisions without relying heavily on others","acceptedParaphrases":["able to work without constant help","able to decide for themselves"],"masteryContexts":[{"contextId":"u6_37_independent_meaning","text":"Good teachers gradually give students more responsibility so that they become independent thinkers.","meaning":"able to think without relying on others","wrongMeanings":["unwilling to listen to anyone","unable to work with other people","likely to copy what others think"]},{"contextId":"u6_37_independent_paraphrase","text":"After moving to a new city for work, Tariq enjoyed being independent and managing his own money and meals.","meaning":"able to manage without relying on others","wrongMeanings":["free from the control of a government","alone because nobody else is nearby","rich enough to buy what is needed"]}],"situationDistractors":["The tour group gathered at the hotel entrance and waited for the coach.","Grandfather planted tomatoes in the garden and watered them every evening.","The referee blew the whistle, and the second half began.","The fisherman repaired his net while the tide went out.","A clerk stamped the forms and handed them back.","Harvest began early because the weather was so warm."],"gapDistractors":[{"contextId":"u6_37_independent_gap_1","answer":"independent","wrong":["popular","tidy","talkative"]},{"contextId":"u6_37_independent_gap_2","answer":"independent","wrong":["hungry","generous","famous"]},{"contextId":"u6_37_independent_gap_3","answer":"independent","wrong":["absent","nervous","famous"]}],"spellingErrors":["independant","indipendent","independint","independet","indepedent","independnt"],"wordFamilyForms":[{"form":"independent","partOfSpeech":"adjective","example":"The course helps adult learners to become independent and plan their own study.","pedagogicallyUseful":true},{"form":"independence","partOfSpeech":"noun","example":"Many teenagers want more independence from their parents when they reach sixteen.","pedagogicallyUseful":true,"altExample":"Moving to another city gave Marco a greater sense of independence."},{"form":"independently","partOfSpeech":"adverb","example":"Please work independently on this task and do not ask your neighbour for answers.","pedagogicallyUseful":true,"altExample":"The students solved the problem independently before comparing answers."}],"masteryPassages":[{"passageId":"u6_37_independent_passage_1","contextId":"u6_37_independent_gap_1","text":"At first the pupils asked for help with every exercise. By the end of term they had become ____ readers who could choose, read and discuss books without a teacher.","answer":"independent"},{"passageId":"u6_37_independent_passage_2","contextId":"u6_37_independent_gap_2","text":"Mehmet’s parents drove him to school until he was fourteen. Then he decided to travel by bus alone, because he wanted to feel more ____.","answer":"independent"}],"contextDependentParaphrases":[],"wrongParaphrases":["willing to follow every rule","unable to finish any task","ready to copy other students"],"misleadingDistractors":["alone and cut off from other people","free from the control of another country","unwilling to listen to anyone’s advice"],"teacherNote":"Taught in its learning and decision-making sense: able to work, think or make decisions without relying heavily on others (an independent learner). It does not mean isolated or lonely, and the political sense (an independent country) is not the focus."}]'::jsonb,'["independence","independently"]'::jsonb,'["an independent learner","independent thinking","independent study"]'::jsonb,'live'),
('vocab_assumption','assumption','noun','something accepted as true without definite proof','[{"senseId":"assumption_1","meaning":"something accepted as true without definite proof","acceptedParaphrases":["belief without proof","idea taken to be true"],"masteryContexts":[{"contextId":"u6_38_assumption_meaning","text":"The manager’s assumption that everyone had read the email proved to be wrong.","meaning":"something accepted as true without proof","wrongMeanings":["a fact that has been checked carefully","a message sent to many people","a rule written in an email"]},{"contextId":"u6_38_assumption_paraphrase","text":"The plan rests on one assumption: that the river will not flood again this year.","meaning":"something taken as true without proof","wrongMeanings":["a result found after a long test","a decision made by the council","a report written by an expert"]}],"situationDistractors":["The tailor measured the customer and wrote the sizes on a small card.","The football pitch was covered in snow, so the match was postponed.","Nilufar finished her tea and washed the cup before leaving.","The bus driver opened the doors and the passengers got off.","Mei watered the plants and closed the curtains for the night.","A delivery van blocked the narrow street for ten minutes."],"gapDistractors":[{"contextId":"u6_38_assumption_gap_1","answer":"assumption","wrong":["complaint","invitation","souvenir"]},{"contextId":"u6_38_assumption_gap_2","answer":"assumption","wrong":["ambulance","accident","invitation"]},{"contextId":"u6_38_assumption_gap_3","answer":"assumption","wrong":["holiday","photograph","invitation"]}],"spellingErrors":["assumtion","asumption","assumpsion","assuption","asumsion","assumtpion"],"masteryPassages":[{"passageId":"u6_38_assumption_passage_1","contextId":"u6_38_assumption_gap_1","text":"The architect designed the bridge for light traffic. Her whole plan rested on one ____: that the town would not grow, which turned out to be wrong.","answer":"assumption"},{"passageId":"u6_38_assumption_passage_2","contextId":"u6_38_assumption_gap_2","text":"Nobody had checked whether the website worked on older phones. The team had simply made an ____ that it would, and customers soon complained.","answer":"assumption"}],"contextDependentParaphrases":[],"wrongParaphrases":["fact with strong proof","plan for next week","question with one answer"],"misleadingDistractors":["a fact that has been checked carefully","a plan for what to do next","a question that needs a quick answer"],"teacherNote":"Countable noun: something accepted as true without definite proof (make an assumption, on the assumption that). It is not evidence, which is information that supports a claim. A careful writer checks an assumption before relying on it."}]'::jsonb,'[]'::jsonb,'["make an assumption","a false assumption","on the assumption that"]'::jsonb,'live'),
('vocab_perspective','perspective','noun','a particular way of thinking about or viewing a situation','[{"senseId":"perspective_1","meaning":"a particular way of thinking about or viewing a situation","acceptedParaphrases":["point of view","way of looking at things"],"masteryContexts":[{"contextId":"u6_39_perspective_meaning","text":"Talking to people of different ages helped Jun to see the problem from a new perspective.","meaning":"a particular way of viewing a situation","wrongMeanings":["a reward for finishing a task","a long journey to a new city","a record of past events"]},{"contextId":"u6_39_perspective_paraphrase","text":"From the perspective of a small business owner, higher taxes make it harder to employ extra staff.","meaning":"a way of thinking shaped by your situation","wrongMeanings":["an opinion with no reasons behind it","a plan to reduce a company’s costs","a habit formed by repeated practice"]}],"situationDistractors":["The marathon runners set off at eight o’clock and crossed the old bridge together.","Two neighbours borrowed each other’s tools and returned them on Sunday.","It rained all morning, but the sun came out after lunch.","The pianist played the final piece and the audience stood up.","Customers queued outside the bakery in the morning cold.","Omar fixed the bicycle chain and wiped his hands."],"gapDistractors":[{"contextId":"u6_39_perspective_gap_1","answer":"perspective","wrong":["invitation","income","supply"]},{"contextId":"u6_39_perspective_gap_2","answer":"perspective","wrong":["pocket","suitcase","birthday"]},{"contextId":"u6_39_perspective_gap_3","answer":"perspective","wrong":["homework","lunch","birthday"]}],"spellingErrors":["perspectiv","perspektive","persepctive","perspectve","prespective","perpective"],"masteryPassages":[{"passageId":"u6_39_perspective_passage_1","contextId":"u6_39_perspective_gap_1","text":"The history lesson usually described the battle from the winning side. When the teacher read letters from the other army, students gained a new ____ on the same events.","answer":"perspective"},{"passageId":"u6_39_perspective_passage_2","contextId":"u6_39_perspective_gap_2","text":"A landlord and a tenant may see the same flat very differently. From the landlord’s ____, a higher rent is fair; from the tenant’s, it is a burden.","answer":"perspective"}],"contextDependentParaphrases":[],"wrongParaphrases":["piece of news","sense of humour","place of work"],"misleadingDistractors":["an opinion that has no reasons behind it","the way objects are drawn to look far away","a long view of a landscape"],"teacherNote":"Countable noun: a particular way of thinking about or viewing a situation (from a different perspective, a perspective on). It is based on experience or reasons, so it is not an opinion with no basis. The art sense (drawing objects so that they look far away) is not taught here."}]'::jsonb,'[]'::jsonb,'["a different perspective","from the perspective of","gain a new perspective"]'::jsonb,'live'),
('vocab_pressure_6','pressure','noun','stress or demands that make someone feel they must perform or act','[{"senseId":"pressure_6_1","meaning":"stress or demands that make someone feel they must perform or act","acceptedParaphrases":["stress from expectations","strong demands to succeed"],"masteryContexts":[{"contextId":"u6_40_pressure_6_meaning","text":"Many young footballers say that the pressure to win every match makes the game less enjoyable.","meaning":"demands that make someone feel they must succeed","wrongMeanings":["the force of weight on a surface","a reward given for winning a game","a friendly wish for good luck"]},{"contextId":"u6_40_pressure_6_paraphrase","text":"Working under pressure is a skill that employers value, because deadlines are common in most jobs.","meaning":"stress caused by demands or deadlines","wrongMeanings":["air that is moving at high speed","a strong wish to relax after work","a gentle request to work later"]}],"situationDistractors":["A couple of tourists photographed the fountain and bought tickets for the boat.","The baker pulled a tray of warm rolls out of the oven.","Rosa waved to her neighbour and watered the flowers on the balcony.","The artist mixed blue and yellow paint to make green.","Visitors walked slowly through the quiet museum.","Grandmother knitted a scarf while the soup cooked."],"gapDistractors":[{"contextId":"u6_40_pressure_6_gap_1","answer":"pressure","wrong":["hunger","thirst","warmth"]},{"contextId":"u6_40_pressure_6_gap_2","answer":"pressure","wrong":["distance","colour","tradition"]},{"contextId":"u6_40_pressure_6_gap_3","answer":"pressure","wrong":["budget","distance","schedule"]}],"spellingErrors":["presure","pressur","pressher","preshure","presssure","pressere"],"masteryPassages":[{"passageId":"u6_40_pressure_6_passage_1","contextId":"u6_40_pressure_6_gap_1","text":"The final was watched by millions. The young goalkeeper said he felt no fear, but the ____ of the occasion made his hands shake.","answer":"pressure"},{"passageId":"u6_40_pressure_6_passage_2","contextId":"u6_40_pressure_6_gap_2","text":"Some students revise best the night before an exam. Others cannot think clearly when they feel ____ from teachers, parents and friends all at once.","answer":"pressure"}],"contextDependentParaphrases":[],"wrongParaphrases":["support from friends","reward for success","time for rest"],"misleadingDistractors":["the force of one object pushing on another","a strong reason that makes you want to work","a gentle suggestion from a friend"],"teacherNote":"Unit 6 item (pressure_6), separate from the Unit 3 pressure item; shares only the lexical spelling list. Sense: stress or demands that make someone feel they must perform or act (pressure to succeed, under pressure). It is different from motivation, which is the wish to do something. The physical sense (air pressure) is not the focus."}]'::jsonb,'[]'::jsonb,'["under pressure","pressure to succeed","peer pressure"]'::jsonb,'live')
insert into public.vocabulary_unit_occurrences
(occurrence_id,vocabulary_id,unit_number,unit_title,set_number,position_in_unit,sense_id,status,active)
